export function LocationMap({
  address = "{{address}}",
  theme = "{{theme}}",
  pinColor = "{{pinColor}}",
  showDirections = {{showDirections}},
}) {
  const dark = theme === "dark";
  return (
    <div style={{ font: "14px system-ui, sans-serif", color: "#241430", maxWidth: 320, borderRadius: 14, overflow: "hidden", border: "1px solid #24143022" }}>
      <div role="img" aria-label={`Map showing location at ${address}`} style={{ height: 160, position: "relative",
        display: "flex", alignItems: "center", justifyContent: "center",
        backgroundColor: dark ? "#241430" : "#FAF7F2",
        backgroundImage: `radial-gradient(${dark ? "#FAF7F233" : "#24143022"} 1px, transparent 1px)`,
        backgroundSize: "14px 14px" }}>
        <span aria-hidden="true" style={{ fontSize: 30, color: pinColor }}>&#128205;</span>
      </div>
      <div style={{ padding: "14px 16px", background: "#FAF7F2", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10 }}>
        <p style={{ margin: 0, color: "#241430cc" }}>{address}</p>
        {showDirections && (
          <a href="#" style={{ flexShrink: 0, color: "#FAF7F2", textDecoration: "none", fontWeight: 700, fontSize: 13,
            padding: "8px 14px", borderRadius: 8, background: pinColor }}>Get directions</a>
        )}
      </div>
    </div>
  );
}
